import json

# Correspondences observable in the supplied examples. The final-g example
# establishes the word-final correspondence g ↔ [k].
observations = [
    ("a", "a", "an’stawteg", "anəstawtek"),
    ("l", "l", "tplutaqan", "ətpəludaɣan"),
    ("p", "p", "tplutaqan", "ətpəludaɣan"),
    ("t", "t", "an’stawteg", "anəstawtek"),
    ("’", "ə", "an’stawteg", "anəstawtek"),
    ("g", "k", "an’stawteg", "anəstawtek"),
]

# Check that the evidence comes from the listed forms, then build the
# phonetic-to-orthographic correspondences.
for spelling, sound, listed_spelling, listed_sound in observations:
    assert spelling in listed_spelling and sound in listed_sound
    if spelling == "g":
        assert listed_spelling.endswith("g") and listed_sound.endswith("k")

sound_to_spelling = {}
for spelling, sound, _, _ in observations:
    if sound != "k":
        assert sound not in sound_to_spelling or sound_to_spelling[sound] == spelling
        sound_to_spelling[sound] = spelling

target = "alaptək"
result = []
for i, sound in enumerate(target):
    if sound == "k" and i == len(target) - 1:
        result.append("g")
    elif sound in sound_to_spelling:
        result.append(sound_to_spelling[sound])
    else:
        print("UNSUPPORTED")
        raise SystemExit

print(json.dumps({
    "final_answer": "".join(result),
    "evidence": {
        "observed_correspondences": ["a:a", "l:l", "p:p", "t:t", "ə:’", "final k:g"],
        "target": target
    },
}, ensure_ascii=False))
