from fractions import Fraction
import json

# A polynomial is a dict {(power_of_tau, power_of_z): Fraction},
# where z = exp(s). Zero coefficients are removed.
def poly(terms):
    return {key: Fraction(value) for key, value in terms.items() if value}

def add(a, b):
    out = dict(a)
    for key, value in b.items():
        out[key] = out.get(key, Fraction(0)) + value
    return poly(out)

def scale(a, factor):
    return poly({key: value * factor for key, value in a.items()})

def multiply(a, b):
    out = {}
    for (i, j), av in a.items():
        for (k, ell), bv in b.items():
            key = (i + k, j + ell)
            out[key] = out.get(key, Fraction(0)) + av * bv
    return poly(out)

def ds(a):
    return poly({(i, j): value * j for (i, j), value in a.items()})

def at_z_one(a):
    out = {}
    for (i, _), value in a.items():
        out[(i, 0)] = out.get((i, 0), Fraction(0)) + value
    return poly(out)

def integrate_s(a, initial):
    # Integrate with respect to s, using d(z^j)/ds = j*z^j.
    if any(j == 0 and value != 0 for (i, j), value in a.items()):
        raise ValueError("A nonzero constant-in-s term has no exponential antiderivative.")
    out = {}
    for (i, j), value in a.items():
        if j:
            out[(i, j)] = value / j
            out[(i, 0)] = out.get((i, 0), Fraction(0)) - value / j
    return add(poly(out), initial)

tau = poly({(1, 0): 1})
z = poly({(0, 1): 1})
one = poly({(0, 0): 1})
tau2 = multiply(tau, tau)

# Initial-curve compatibility gives q(0,tau) = du/dtau = 2*tau.
q0 = scale(tau, 2)
# pq=u on the initial curve, so p(0,tau) = tau/2 (for generic tau).
p0 = scale(tau, Fraction(1, 2))

# Charpit equations: p_s=p, q_s=q, x_s=q, y_s=p, u_s=2pq.
p = multiply(p0, z)
q = multiply(q0, z)
derived = (
    integrate_s(q, poly({})),
    integrate_s(p, tau),
    integrate_s(scale(multiply(p, q), 2), tau2),
)

options = [
    (
        scale(multiply(tau, add(z, scale(one, -1))), 3),
        scale(multiply(tau, add(poly({(0, -1): 1}), one)), Fraction(1, 2)),
        multiply(tau2, poly({(0, -2): 1})),
    ),
    (
        scale(multiply(tau, add(z, scale(one, -1))), 2),
        multiply(tau, add(scale(poly({(0, 2): 1}), 2), scale(one, -1))),
        scale(multiply(tau2, add(one, poly({(0, -2): 1}))), Fraction(1, 2)),
    ),
    (
        scale(multiply(tau, add(z, scale(one, -1))), 2),
        scale(multiply(tau, add(z, one)), Fraction(1, 2)),
        multiply(tau2, poly({(0, 2): 1})),
    ),
    (
        multiply(tau, add(poly({(0, -1): 1}), scale(one, -1))),
        scale(multiply(tau, add(poly({(0, -1): 1}), scale(one, Fraction(-3, 2)))), -2),
        multiply(tau2, add(scale(poly({(0, -2): 1}), 2), scale(one, -1))),
    ),
]

# Check each listed set directly against initial data and the Charpit ODEs.
valid = []
for index, (x, y, u) in enumerate(options, start=1):
    initial_ok = (
        at_z_one(x) == poly({})
        and at_z_one(y) == tau
        and at_z_one(u) == tau2
    )
    q_candidate, p_candidate = ds(x), ds(y)
    charpit_ok = (
        ds(q_candidate) == q_candidate
        and ds(p_candidate) == p_candidate
        and ds(u) == scale(multiply(p_candidate, q_candidate), 2)
    )
    if initial_ok and charpit_ok and (x, y, u) == derived:
        valid.append(index)

if len(valid) != 1:
    result = {"final_answer": "UNSUPPORTED", "evidence": {"valid_options": valid}}
else:
    result = {
        "final_answer": f"Option {valid[0]}",
        "evidence": {
            "initial_slopes": {"p0": "tau/2", "q0": "2*tau"},
            "charpit_solution": {
                "x": "2*tau*(exp(s)-1)",
                "y": "tau*(exp(s)+1)/2",
                "u": "tau^2*exp(2*s)",
            },
            "verified_options": valid,
        },
    }

print(json.dumps(result, separators=(",", ":")))
