# The given examples show consonant + ’ corresponding to that consonant
# followed by ə (for example, n’ -> nə and g’ -> gə).
target = "alaptək"
submitted = "alapt’k"

examples = [
    ("an’stawteg", "anəstawtek", "n’", "nə"),
    ("g’p’ta’q", "gəbədāx", "g’", "gə"),
]

def evidence_holds():
    return all(
        marker in spelling and sound in pronunciation
        for spelling, pronunciation, marker, sound in examples
    )

vowels = set("aeiou")
consonants = set("bcdfghjklmnpqrstvwxyz")

def encode(pronunciation):
    result = []
    for i, ch in enumerate(pronunciation):
        if ch == "ə":
            if (i == 0 or i + 1 == len(pronunciation)
                    or pronunciation[i - 1] not in consonants
                    or pronunciation[i + 1] not in consonants):
                return None
            result[-1] += "’"
        elif ch in vowels or ch in consonants:
            result.append(ch)
        else:
            return None
    return "".join(result)

def decode(spelling):
    result = []
    i = 0
    while i < len(spelling):
        ch = spelling[i]
        if ch not in vowels and ch not in consonants:
            return None
        result.append(ch)
        i += 1
        if i < len(spelling) and spelling[i] == "’":
            if ch not in consonants:
                return None
            result.append("ə")
            i += 1
    return "".join(result)

expected = encode(target)
print("Expected Listuguj spelling:", expected)
print("Submitted spelling:", submitted)
print("Round-trip pronunciation:", decode(submitted))
print("Example support for consonant + ’ = consonant + ə:",
      "PASS" if evidence_holds() else "FAIL")

if expected is None or not evidence_holds():
    print("UNSUPPORTED")
    print("CHECK UNKNOWN")
elif expected == submitted and decode(submitted) == target:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
