import itertools
import json

# Adjective classes and the precedence constraints established by the examples.
classes = (
    "material", "origin", "age", "purpose",
    "opinion", "color", "size", "shape"
)
constraints = (
    ("material", "origin"),
    ("origin", "age"),
    ("age", "purpose"),
    ("purpose", "opinion"),
    ("opinion", "color"),
    ("size", "shape"),
)

options = {
    "A": ("shape", "size", "age", "purpose", "opinion", "color"),
    "B": ("material", "origin", "age", "purpose", "opinion", "color", "size", "shape"),
    "C": ("shape", "age", "purpose", "opinion", "color", "origin", "material"),
    "D": ("age", "purpose", "opinion", "color", "size", "shape"),
    "E": ("material", "origin", "age", "purpose", "opinion", "color"),
    "F": ("material", "origin", "age", "purpose", "opinion", "color", "size"),
    "G": ("size", "shape", "age", "purpose", "opinion", "color"),
    "H": ("origin", "age", "purpose", "opinion", "color", "size", "shape"),
    "I": ("material", "origin", "age", "purpose", "opinion", "color", "shape"),
    "J": ("shape", "size", "age", "purpose", "opinion", "color", "origin"),
}

models = []
for order in itertools.permutations(classes):
    rank = {category: i for i, category in enumerate(order)}
    if all(rank[left] < rank[right] for left, right in constraints):
        valid = tuple(
            letter for letter, sequence in options.items()
            if all(rank[a] < rank[b] for a, b in zip(sequence, sequence[1:]))
        )
        # E is implied by the constraints, so K cannot apply in these models.
        models.append((order, valid))

answer_sets = sorted({valid for _, valid in models})
if len(answer_sets) == 1:
    final_answer = "".join(answer_sets[0])
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "models": len(models),
    "derived_precedence": [f"{a}<{b}" for a, b in constraints],
    "distinct_answer_sets": ["".join(s) for s in answer_sets],
}
if len(answer_sets) > 1:
    evidence["witnesses"] = [
        {
            "class_order": list(order),
            "valid_choices": "".join(valid),
        }
        for order, valid in models
        if valid in (answer_sets[0], answer_sets[-1])
    ][:2]

print(json.dumps({"final_answer": final_answer, "evidence": evidence}, separators=(",", ":")))
