from fractions import Fraction
import json

c = Fraction(20, -24) - (2 + -3)

# Differentiate the given polynomial term by term.
original = {
    4: Fraction(1, 16),
    3: -c,
    2: Fraction(1, 8),
    1: Fraction(0),
    0: Fraction(1),
}
derivative = {
    exponent - 1: exponent * coefficient
    for exponent, coefficient in original.items()
    if exponent > 0
}

# The derivative has zero constant term, so extract s and factor the
# remaining quadratic using its exact discriminant.
a = derivative[3]
b = derivative[2]
d = derivative[1]
discriminant = b * b - 4 * a * d

if derivative.get(0, Fraction(0)) != 0 or discriminant != 0:
    result = "UNSUPPORTED"
    evidence = {"c": str(c), "reason": "factorization procedure did not settle the polynomial"}
else:
    root = -b / (2 * a)

    def fmt(value):
        return str(value)

    if root > 0:
        linear_factor = f"s - {fmt(root)}"
    elif root < 0:
        linear_factor = f"s + {fmt(-root)}"
    else:
        linear_factor = "s"

    result = f"({fmt(a)})*s*({linear_factor})^2"
    evidence = {
        "c": str(c),
        "k_coefficients_descending": [
            str(derivative[3]), str(derivative[2]),
            str(derivative[1]), str(derivative.get(0, Fraction(0)))
        ],
        "quadratic_discriminant": str(discriminant),
        "repeated_root": str(root),
    }

print(json.dumps({"final_answer": result, "evidence": evidence}))
