from fractions import Fraction
from math import gcd, lcm
import json

# Represent a + b*sqrt(39) exactly by (a, b).
def add(u, v):
    return (u[0] + v[0], u[1] + v[1])

def neg(u):
    return (-u[0], -u[1])

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    return (u[0] * v[0] + 39 * u[1] * v[1],
            u[0] * v[1] + u[1] * v[0])

def div(u, v):
    denominator = v[0] * v[0] - 39 * v[1] * v[1]
    assert denominator != 0
    return ((u[0] * v[0] - 39 * u[1] * v[1]) / denominator,
            (u[1] * v[0] - u[0] * v[1]) / denominator)

def sign(u):
    a, b = u
    if a == 0:
        return (b > 0) - (b < 0)
    if b == 0 or (a > 0 and b > 0):
        return 1
    if a < 0 and b < 0:
        return -1
    comparison = a * a - 39 * b * b
    if comparison == 0:
        return 0
    return (1 if comparison > 0 else -1) * (1 if a > 0 else -1)

def radical_string(u):
    a, b = u
    denominator = lcm(a.denominator, b.denominator)
    A = a.numerator * (denominator // a.denominator)
    B = b.numerator * (denominator // b.denominator)
    common = gcd(gcd(abs(A), abs(B)), denominator)
    A, B, denominator = A // common, B // common, denominator // common

    if B == 0:
        numerator = str(A)
    else:
        radical = "sqrt(39)" if abs(B) == 1 else f"{abs(B)}*sqrt(39)"
        if A == 0:
            numerator = ("-" if B < 0 else "") + radical
        else:
            numerator = f"{A}{'+' if B > 0 else '-'}{radical}"
    return numerator if denominator == 1 else f"({numerator})/{denominator}"

# On the closed feasible set, extrema of xyz are either on the boundary
# (where xyz=0) or at an interior stationary point. At an interior
# stationary point two variables must be equal.
# If the repeated variable is a, then 3a^2 - 18a + 14 = 0.
candidates = []
for a in [(Fraction(3), Fraction(-1, 3)),
          (Fraction(3), Fraction(1, 3))]:
    third = sub((Fraction(9), Fraction(0)), mul((Fraction(2), Fraction(0)), a))
    if sign(a) > 0 and sign(third) > 0:
        candidates.append(mul(mul(a, a), third))

boundary_product = (Fraction(0), Fraction(0))
assert candidates and all(sign(sub(r, boundary_product)) > 0 for r in candidates)
r_max = candidates[0]
for r in candidates[1:]:
    if sign(sub(r, r_max)) > 0:
        r_max = r

# For p=x+y+z=9, q=xy+yz+zx=14:
# sum xy/(x+y) = (q^2 + p*xyz)/(p*q - xyz),
# so the requested expression is 18 - 2*sum xy/(x+y).
p, q = Fraction(9), Fraction(14)
S = div(add((q * q, Fraction(0)), mul((p, Fraction(0)), r_max)),
        sub((p * q, Fraction(0)), r_max))
answer = sub((Fraction(18), Fraction(0)), mul((Fraction(2), Fraction(0)), S))

print(json.dumps({
    "final_answer": radical_string(answer),
    "evidence": [
        f"Maximum feasible xyz = {radical_string(r_max)}; the other repeated-root candidate is infeasible.",
        "The symmetric sum identity gives the objective as 18 - 2*(196+9*xyz)/(126-xyz), decreasing in xyz."
    ]
}))
