import json
from itertools import product

def subsets(n):
    return [
        {i for i in range(n) if mask & (1 << i)}
        for mask in range(1 << n)
    ]

# Test the shared form: some X is not Y -> some Y is not X.
def test_converse_form():
    for n in (1, 2):
        sets = subsets(n)
        for x, y in product(sets, repeat=2):
            premise = bool(x - y)
            conclusion = bool(y - x)
            if premise and not conclusion:
                return False, {"domain_size": n, "X": sorted(x), "Y": sorted(y)}
    return True, None

# Test: some person is not selfish -> not everyone is selfish.
def test_paraphrase():
    for n in (1, 2):
        for selfish in subsets(n):
            premise = bool(set(range(n)) - selfish)
            conclusion = selfish != set(range(n))
            if premise and not conclusion:
                return False, None
    return True, None

original_valid, counterexample = test_converse_form()
option_validity = {
    "A": test_converse_form()[0],
    "B": test_paraphrase()[0],
    "C": test_converse_form()[0],
    "D": test_converse_form()[0],
}

# The requested option is the one whose validity differs from the original.
different = [k for k, v in option_validity.items() if v != original_valid]
result = {
    "final_answer": different[0] if len(different) == 1 else "UNSUPPORTED",
    "evidence": {
        "original_valid": original_valid,
        "option_validity": option_validity,
        "counterexample_to_original_form": counterexample,
    },
}
print(json.dumps(result, separators=(",", ":")))
