import json
import math

# Coordinates are treated as rounded measurements; geometric comparisons use
# tolerances appropriate to the stated five-decimal rounding.
segments_text = """
0.0,16.81045 0.0,14.80251
0.0,0.0 0.0,14.80251
-0.0,21.72644 0.0,16.81045
-15.59808,14.80251 -15.59808,21.72644
-9.98277,8.80251 0.0,8.80251
9.07607,21.72644 9.07607,14.80251
5.35488,14.80251 0.0,14.80251
-0.0,21.72644 9.07607,21.72644
0.0,14.80251 -15.59808,14.80251
-5.19615,11.80251 0.0,14.80251
0.0,8.80251 -5.19615,11.80251
-15.59808,21.72644 -0.0,21.72644
9.07607,14.80251 9.07607,9.32558
-15.59808,8.80251 -9.98277,8.80251
9.07607,9.32558 9.07607,0.0
0.0,14.80251 -0.0,21.72644
9.07607,14.80251 5.35488,14.80251
-15.59808,14.80251 -15.59808,13.48251
-15.59808,13.48251 -15.59808,8.80251
0.0,14.80251 9.07607,14.80251
"""

EPS = 1e-4
GEOM_EPS = 2e-4

def parse_point(s):
    x, y = s.split(",")
    return (float(x), float(y))

segments = []
for line in segments_text.strip().splitlines():
    a, b = line.split()
    segments.append((parse_point(a), parse_point(b)))

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def close_points(a, b, tol=EPS):
    return math.hypot(a[0] - b[0], a[1] - b[1]) <= tol

def point_on_segment(p, a, b, tol=GEOM_EPS):
    v, w = sub(b, a), sub(p, a)
    scale = max(1.0, math.hypot(*v))
    if abs(cross(v, w)) > tol * scale:
        return False
    return dot(w, v) >= -tol and dot(sub(p, b), v) <= tol

def segment_intersections(a, b, c, d):
    r, s = sub(b, a), sub(d, c)
    den = cross(r, s)
    ca = sub(c, a)
    out = []
    if abs(den) > 1e-12:
        t = cross(ca, s) / den
        u = cross(ca, r) / den
        if -1e-9 <= t <= 1 + 1e-9 and -1e-9 <= u <= 1 + 1e-9:
            out.append((a[0] + t * r[0], a[1] + t * r[1]))
    elif abs(cross(ca, r)) <= GEOM_EPS * max(1.0, math.hypot(*r)):
        for p in (a, b, c, d):
            if point_on_segment(p, a, b) and point_on_segment(p, c, d):
                out.append(p)
    return out

# Collect segment endpoints and all crossings/overlap endpoints, then split
# every input segment at those locations.
split_points = [[a, b] for a, b in segments]
for i in range(len(segments)):
    for j in range(i + 1, len(segments)):
        for p in segment_intersections(*segments[i], *segments[j]):
            split_points[i].append(p)
            split_points[j].append(p)

vertices = []
def vertex_id(p):
    for i, q in enumerate(vertices):
        if close_points(p, q):
            return i
    vertices.append(p)
    return len(vertices) - 1

edges = set()
for (a, b), pts in zip(segments, split_points):
    v = sub(b, a)
    denom = dot(v, v)
    ordered = []
    for p in pts:
        t = dot(sub(p, a), v) / denom if denom else 0.0
        if -1e-8 <= t <= 1 + 1e-8:
            ordered.append((min(1.0, max(0.0, t)), vertex_id(p)))
    ordered.sort()
    ids = []
    for _, k in ordered:
        if not ids or ids[-1] != k:
            ids.append(k)
    for u, w in zip(ids, ids[1:]):
        if u != w and math.hypot(vertices[u][0] - vertices[w][0],
                                 vertices[u][1] - vertices[w][1]) > EPS:
            edges.add(tuple(sorted((u, w))))

adj = [set() for _ in vertices]
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

def polygon_area(poly):
    return 0.5 * sum(cross(poly[(i + 1) % len(poly)], poly[i])
                     for i in range(len(poly)))

def simplify_cycle(ids):
    pts = [vertices[i] for i in ids]
    changed = True
    while changed and len(pts) >= 3:
        changed = False
        keep = []
        n = len(pts)
        for i in range(n):
            a, b, c = pts[i - 1], pts[i], pts[(i + 1) % n]
            u, v = sub(b, a), sub(c, b)
            if abs(cross(u, v)) <= GEOM_EPS * max(1.0, math.hypot(*u), math.hypot(*v)) and dot(u, v) >= -GEOM_EPS:
                changed = True
            else:
                keep.append(b)
        pts = keep
    return pts

def point_in_polygon(p, poly):
    inside = False
    x, y = p
    for i in range(len(poly)):
        a, b = poly[i], poly[(i + 1) % len(poly)]
        if point_on_segment(p, a, b):
            return 0
        if (a[1] > y) != (b[1] > y):
            xx = a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if xx > x:
                inside = not inside
    return 1 if inside else -1

def has_internal_drawn_edge(poly):
    for u, v in edges:
        a, b = vertices[u], vertices[v]
        mid = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
        if point_in_polygon(mid, poly) == 1:
            return True
    return False

def parallel(u, v):
    return abs(cross(u, v)) <= GEOM_EPS * max(1.0, math.hypot(*u), math.hypot(*v))

def classify(poly):
    n = len(poly)
    if n < 3 or abs(polygon_area(poly)) < 1e-5:
        return None
    if has_internal_drawn_edge(poly):
        return None

    vecs = [sub(poly[(i + 1) % n], poly[i]) for i in range(n)]
    lengths = [math.hypot(*v) for v in vecs]
    crosses = [cross(vecs[i], vecs[(i + 1) % n]) for i in range(n)]
    nonzero = [x for x in crosses if abs(x) > GEOM_EPS]
    if not nonzero:
        return None
    convex = all(x > 0 for x in nonzero) or all(x < 0 for x in nonzero)

    if n == 3:
        right = any(abs(dot(vecs[i], vecs[(i + 1) % 3])) <=
                    GEOM_EPS * max(1.0, lengths[i] * lengths[(i + 1) % 3])
                    for i in range(3))
        return 4 if right else 3

    if n == 4:
        p01 = parallel(vecs[0], vecs[2])
        p12 = parallel(vecs[1], vecs[3])
        right = all(abs(dot(vecs[i], vecs[(i + 1) % 4])) <=
                    GEOM_EPS * max(1.0, lengths[i] * lengths[(i + 1) % 4])
                    for i in range(4))
        equal_sides = max(lengths) - min(lengths) <= GEOM_EPS * max(lengths)
        if p01 and p12:
            if right:
                return 2 if equal_sides else 1
            return 5
        if p01 != p12:
            return 6
        return None

    if n == 5:
        if not convex:
            return 8
        regular = (max(lengths) - min(lengths) <= GEOM_EPS * max(lengths)
                   and all(abs(cross(vecs[i], vecs[(i + 1) % n])) /
                           (lengths[i] * lengths[(i + 1) % n]) - math.cos(2 * math.pi / 5)
                           <= 1e-3 for i in range(n)))
        if regular:
            return 9
        return 7

    if n == 6 and convex:
        regular = (max(lengths) - min(lengths) <= GEOM_EPS * max(lengths)
                   and all(abs(cross(vecs[i], vecs[(i + 1) % n])) /
                           (lengths[i] * lengths[(i + 1) % n]) - 0.5
                           <= 1e-3 for i in range(n)))
        if regular:
            return 10
    return None

found = set()
cycle_count = 0
limit = 250000

# Enumerate each simple graph cycle once: its first vertex is its smallest
# indexed vertex, and the two traversal directions are deduplicated.
for start in range(len(vertices)):
    path = [start]
    used = {start}

    def dfs(cur):
        global cycle_count
        if cycle_count > limit:
            return
        for nxt in adj[cur]:
            if nxt == start and len(path) >= 3:
                if path[1] < path[-1]:
                    cycle_count += 1
                    poly = simplify_cycle(path)
                    kind = classify(poly)
                    if kind is not None:
                        found.add(kind)
                continue
            if nxt <= start or nxt in used:
                continue
            used.add(nxt)
            path.append(nxt)
            dfs(nxt)
            path.pop()
            used.remove(nxt)

    dfs(start)

option_sets = {
    "A": {1, 8}, "B": set(), "C": {2}, "D": {5, 9}, "E": {8},
    "F": {1, 8, 5}, "G": {1, 8, 3, 4}, "H": {1},
    "I": {1, 5}, "J": {1, 8, 4, 9}, "K": {1, 8, 6},
    "L": {8, 3, 7}, "M": {2, 3}, "N": {1, 7},
    "O": {8, 2, 6, 10}, "P": {1, 8, 2},
}
matches = [letter for letter, shape_set in option_sets.items()
           if shape_set == found]

if cycle_count > limit or len(matches) != 1:
    result = "UNSUPPORTED"
else:
    result = matches[0]

print(json.dumps({
    "final_answer": result,
    "evidence": {
        "detected_shape_numbers": sorted(found),
        "enumerated_cycles": cycle_count
    }
}, separators=(",", ":")))
