M -15.59808,14.80251 L -15.59808,13.48251 L -15.59808,8.80251
M 0.0,14.80251 L 9.07607,14.80251"""

tokens = re.findall(r"[ML]|[-+]?(?:\d+(?:\.\d*)?|\.\d+)", path)
segments = []
i = 0
current = None
while i < len(tokens):
    command = tokens[i]
    i += 1
    x, y = F(tokens[i]), F(tokens[i + 1])
    i += 2
    point = (x, y)
    if command == "M":
        current = point
    else:
        segments.append((current, point))
        current = point

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def on_segment(p, a, b):
    return cross(sub(p, a), sub(b, a)) == 0 and all(
        min(a[k], b[k]) <= p[k] <= max(a[k], b[k]) for k in (0, 1)
    )

# Split segments at every endpoint or intersection, making a planar graph.
vertices = set(p for seg in segments for p in seg)
for i, (a, b) in enumerate(segments):
    r = sub(b, a)
    for c, d in segments[i + 1:]:
        s = sub(d, c)
        den = cross(r, s)
        ca = sub(c, a)
        if den:
            t, u = F(cross(ca, s), den), F(cross(ca, r), den)
            if 0 <= t <= 1 and 0 <= u <= 1:
                vertices.add((a[0] + t * r[0], a[1] + t * r[1]))
        elif cross(ca, r) == 0:  # Collinear segments: split at overlap endpoints.
            for p in (a, b, c, d):
                if on_segment(p, a, b) and on_segment(p, c, d):
                    vertices.add(p)

adj = {p: set() for p in vertices}
for a, b in segments:
    points = [p for p in vertices if on_segment(p, a, b)]
    axis = 0 if a[0] != b[0] else 1
    points.sort(key=lambda p: p[axis], reverse=(a[axis] > b[axis]))
    for p, q in zip(points, points[1:]):
        if p != q:
            adj[p].add(q)
            adj[q].add(p)

# Enumerate every simple cycle once.
cycles = set()
for start in sorted(vertices):
    def walk(path_nodes):
        here = path_nodes[-1]
        for nxt in adj[here]:
            if nxt == start and len(path_nodes) >= 3:
                if path_nodes[1] < path_nodes[-1]:
                    cycles.add(tuple(path_nodes))
            elif nxt > start and nxt not in path_nodes:
                walk(path_nodes + [nxt])
    walk([start])

def simplify(poly):
    poly = list(poly)
    changed = True
    while changed and len(poly) >= 3:
        changed = False
        keep = []
        n = len(poly)
        for j, p in enumerate(poly):
            if cross(sub(p, poly[j - 1]), sub(poly[(j + 1) % n], p)) == 0:
                changed = True
            else:
                keep.append(p)
        poly = keep
    return poly

def area2(poly):
    return sum(cross(poly[i], poly[(i + 1) % len(poly)])
               for i in range(len(poly)))

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def close(a, b):
    return abs(float(a - b)) <= 1e-4 * max(1.0, abs(float(a)), abs(float(b)))

def regular(poly):
    edges = [sub(poly[(i + 1) % len(poly)], poly[i])
             for i in range(len(poly))]
    lengths2 = [dot(e, e) for e in edges]
    if not all(close(v, lengths2[0]) for v in lengths2):
        return False
    turns = [(dot(edges[i], edges[(i + 1) % len(edges)]),
              cross(edges[i], edges[(i + 1) % len(edges)]))
             for i in range(len(edges))]
    return (all(close(t[0], turns[0][0]) for t in turns)
            and all(close(t[1], turns[0][1]) for t in turns))

found = set()
witness = {}

for cycle in cycles:
    poly = simplify(cycle)
    n = len(poly)
    if n < 3 or area2(poly) == 0:
        continue

    edges = [sub(poly[(i + 1) % n], poly[i]) for i in range(n)]
    turns = [cross(edges[i], edges[(i + 1) % n]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)

    label = None
    if n == 3:
        right = any(dot(sub(poly[i - 1], poly[i]),
                        sub(poly[(i + 1) % n], poly[i])) == 0
                    for i in range(n))
        label = 4 if right else 3
    elif n == 4 and convex:
        parallel_pairs = (
            cross(edges[0], edges[2]) == 0,
            cross(edges[1], edges[3]) == 0,
        )
        parallelogram = all(parallel_pairs)
        right = any(dot(sub(poly[i - 1], poly[i]),
                        sub(poly[(i + 1) % n], poly[i])) == 0
                    for i in range(n))
        if parallelogram and right:
            label = 2 if close(dot(edges[0], edges[0]),
                               dot(edges[1], edges[1])) else 1
        elif parallelogram:
            label = 5
        elif sum(parallel_pairs) == 1:
            label = 6
    elif n == 5:
        label = 9 if convex and regular(poly) else (7 if convex else 8)
    elif n == 6 and convex and regular(poly):
        label = 10

    if label is not None:
        found.add(label)
        witness.setdefault(label, poly)

selected = {1, 5}  # Option (I)
print("Selected option (I) contains:", sorted(selected))
print("Shapes found by exhaustive simple-cycle enumeration:", sorted(found))
for label in sorted(found):
    pts = [(round(float(x), 5), round(float(y), 5))
           for x, y in witness[label]]
    print(f"Shape {label} witness:", pts)

if found == selected:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
