def calculate(node):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool):
            return node.value
        if isinstance(node.value, int):
            return Fraction(node.value)
        raise ValueError("Unsupported constant")
    if isinstance(node, ast.UnaryOp):
        value = calculate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
    if isinstance(node, ast.BoolOp):
        values = [calculate(item) for item in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.BinOp):
        left, right = calculate(node.left), calculate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        args = [calculate(arg) for arg in node.args]
        if node.func.id == "max":
            return max(args)
        if node.func.id == "min":
            return min(args)
    if isinstance(node, ast.Compare):
        left = calculate(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = calculate(comparator)
            if isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            elif isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            else:
                raise ValueError("Unsupported comparison")
            if not result:
                return False
            left = right
        return True
    raise ValueError("Unsupported syntax: " + ast.dump(node))

def evaluate(expression):
    def capital_replacement(match):
        country, city = match.group(1), match.group(2)
        key = (country, city)
        if key not in capitals:
            raise ValueError("Unknown capital assertion: " + str(key))
        return str(capitals[key])

    expression = re.sub(
        r"The capital of (?:the )?([A-Za-z]+) is ([A-Za-z]+)\.",
        capital_replacement,
        expression,
    )
    expression = expression.replace("is less than or equal to", "<=")
    expression = expression.replace("is greater than", ">")
    tree = ast.parse(expression, mode="eval")
    return bool(calculate(tree.body))

values = [evaluate(expression) for expression in expressions]
winners = [label for label, value in zip("ABCDE", values) if value]
assert len(winners) == 1, "The computation did not yield exactly one true expression"
print(json.dumps({
    "final_answer": winners[0],
    "evidence": {"A": values[0], "B": values[1], "C": values[2],
                 "D": values[3], "E": values[4]}
}))
