from itertools import permutations
import json

# Categories: opinion, purpose, size, color, age, shape, origin, material.
# These are the distinct cross-category ordering patterns in the givens.
categories = ("O", "P", "S", "C", "A", "H", "R", "M")
given_patterns = (
    ("O", "C", "A"),  # good gray archaic piano
    ("S", "C"),       # e.g. massive yellow bottle
    ("O", "P"),       # e.g. lovely snorkeling banana
    ("A", "H"),       # e.g. ancient spherical fire extinguisher
    ("M", "R"),       # e.g. glass vietnamese drill
    ("P", "S", "H"),  # driving midsize rectangular toolbox
)

options = {
    "A": ("O", "P", "S", "C", "A", "H", "M"),
    "B": ("O", "P", "S", "C", "A", "H", "R"),
    "C": ("R", "S", "C", "A", "H", "P", "O"),
    "D": ("M", "S", "C", "A", "H", "P", "O"),
    "E": ("M", "R", "S", "C", "A", "H", "P"),
    "F": ("O", "P", "S", "C", "A", "H", "R", "M"),
    "G": ("O", "P", "S", "C", "A", "H"),
    "H": ("R", "M", "S", "C", "A", "H", "P"),
    "I": ("P", "S", "C", "A", "H", "M", "R"),
    "J": ("R", "M", "S", "C", "A", "H"),
}

def ordered(seq, rank):
    return all(rank[x] < rank[y] for x, y in zip(seq, seq[1:]))

answer_sets = {}
model_count = 0
for order in permutations(categories):
    rank = {category: i for i, category in enumerate(order)}
    if not all(ordered(pattern, rank) for pattern in given_patterns):
        continue
    model_count += 1
    answer = "".join(
        letter for letter, sequence in options.items()
        if ordered(sequence, rank)
    )
    answer_sets.setdefault(answer, order)

# If distinct total category orders consistent with the givens yield different
# selections, the problem does not determine one concatenated answer.
if len(answer_sets) == 1:
    final_answer = next(iter(answer_sets))
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "consistent_category_orders": model_count,
    "distinct_selections": len(answer_sets),
    "witness_selections": [
        {"selection": answer, "category_order": "".join(order)}
        for answer, order in list(answer_sets.items())[:2]
    ],
}
print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
