import itertools
import json

# Languages each person can speak, including their native language.
languages = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "Germany": {"Korean", "French", "English", "German"},
}

def can_communicate(a, b):
    return bool(languages[a] & languages[b])

valid_orders = []
for order in itertools.permutations(languages):  # rooms 1 through 4
    room = {nationality: i + 1 for i, nationality in enumerate(order)}

    if room["South Korea"] <= room["Germany"]:
        continue

    neighbors = {
        nationality: [
            order[j] for j in (i - 1, i + 1) if 0 <= j < 4
        ]
        for i, nationality in enumerate(order)
    }

    if any(can_communicate("South Korea", n)
           for n in neighbors["South Korea"]):
        continue
    if any(can_communicate("France", n) for n in neighbors["France"]):
        continue
    if sum(can_communicate("Britain", n)
           for n in neighbors["Britain"]) != 1:
        continue

    valid_orders.append(order)

options = {
    ("Britain", "Germany", "South Korea", "France"): "A",
    ("France", "Britain", "Germany", "South Korea"): "B",
    ("Germany", "Britain", "France", "South Korea"): "C",
    ("Germany", "Britain", "South Korea", "France"): "D",
}

answers = [options[o] for o in valid_orders if o in options]
final_answer = answers[0] if len(valid_orders) == 1 and len(answers) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "valid_room_orders": [list(o) for o in valid_orders],
        "valid_order_count": len(valid_orders)
    }
}))
